def provider_name(code):
    local = {"A": "Alpha"}
    if code not in local:
        raise ValueError("unknown provider")
    return local[code]

def submit(code, fetch):
    try:
        payload = fetch()
    except TimeoutError:
        payload = fetch()
    return {"provider": provider_name(code), "payload": payload}

