def decode(record):
    if "provider_code" in record:
        return record["provider_code"]
    if "provider" in record:
        return record["provider"]
    if "legacy_provider" in record:
        return record["legacy_provider"]
    raise ValueError("missing provider")

files.tests/test_codec.py:
import unittest
from codec import decode

class CodecTests(unittest.TestCase):
    def test_current_record(self):
        self.assertEqual(decode({"provider_code": "B"}), "B")

    def test_stored_v1_record(self):
        self.assertEqual(decode({"provider": "A"}), "A")

    def test_unused_v0_rejected(self):
        with self.assertRaises(ValueError):
            decode({"legacy_provider": "A"})

    def test_missing_provider_rejected(self):
        with self.assertRaises(ValueError):
            decode({"other": "A"})
